def find_longest(numbers: list[int]) -> int:
    if not numbers:
        raise ValueError("Input list must not be empty")

    max_digits = -1
    result = numbers[0]

    for num in numbers:
        current_digits = len(str(abs(num)))
        if current_digits > max_digits:
            max_digits = current_digits
            result = num

    return result
